'use strict';
function navigate(){const requested=location.hash.slice(1).split('/')[0];const pages=['home','quran-reader','adhkar-reader','prayer-tools'];const page=pages.includes(requested)?requested:'home';for(const id of pages)document.getElementById(id).hidden=id!==page;document.querySelectorAll('[data-nav]').forEach(link=>{if(link.dataset.nav===page)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});document.title=({home:'القرآن الكريم والأذكار ومواقيت الصلاة','quran-reader':'القرآن الكريم','adhkar-reader':'الأذكار والأدعية','prayer-tools':'الصلاة والقبلة والهجري'})[page]+' | النور';document.getElementById('primary-nav').classList.remove('is-open');document.getElementById('menu-toggle').setAttribute('aria-expanded','false');window.scrollTo(0,0);if(page==='quran-reader'&&window.__quranShown)window.__quranShown();}
document.getElementById('menu-toggle').addEventListener('click',()=>{const button=document.getElementById('menu-toggle');const open=button.getAttribute('aria-expanded')!=='true';button.setAttribute('aria-expanded',String(open));document.getElementById('primary-nav').classList.toggle('is-open',open);});
window.addEventListener('hashchange',navigate);

