let surahIndex=0,verseIndex=0,fontSize=34,readingPage=0,pendingOpen=false,pendingFocus=false;
const PAGE_SIZE=10,BOOKMARK_KEY='skillpost-quran-position-v1';
function pageRanges(count,size=PAGE_SIZE){if(!Number.isInteger(count)||count<0||!Number.isInteger(size)||size<1)return [];return Array.from({length:Math.ceil(count/size)},(_,index)=>({start:index*size,end:Math.min(count,(index+1)*size)}));}
function selectedAyah(){return quranData[surahIndex].verses[verseIndex];}
function updateTafsir(){const surah=quranData[surahIndex],ayah=selectedAyah();const ref='سورة '+surah.name+' — الآية '+ayah.number;document.getElementById('selected-reference').textContent=ref;document.getElementById('tafsir-reference').textContent='تفسير '+ref;document.getElementById('tafsir-text').textContent=ayah.tafsir;}
function setTafsir(open){const panel=document.getElementById('tafsir-panel'),button=document.getElementById('tafsir-toggle');panel.hidden=!open;button.setAttribute('aria-expanded',String(open));button.textContent=open?'إخفاء التفسير':'إظهار التفسير';}
function focusVerse(){const marker=document.getElementById('ayah-'+selectedAyah().number);if(marker){marker.focus({preventScroll:true});marker.scrollIntoView({block:'center',behavior:'auto'});}}
const surahLoads=new Map();
function loadSurah(i){const s=quranData[i];if(s.verses)return Promise.resolve(s);if(!surahLoads.has(i))surahLoads.set(i,fetch('/data/quran/'+String(s.id).padStart(3,'0')+'.json',{credentials:'omit'}).then(r=>{if(!r.ok)throw new Error('HTTP '+r.status);return r.json();}).then(d=>{if(d.surah!==s.id||!Array.isArray(d.verses)||d.verses.length!==s.count)throw new Error('bad data');s.verses=d.verses;return s;}).catch(e=>{surahLoads.delete(i);throw e;}));return surahLoads.get(i);}
function selectVerse(index,open=false,focus=false){if(!Number.isInteger(index)||index<0||index>=quranData[surahIndex].count)return false;if(!quranData[surahIndex].verses){verseIndex=index;readingPage=Math.floor(index/PAGE_SIZE);pendingOpen=open;pendingFocus=focus;renderQuran();return true;}verseIndex=index;readingPage=Math.floor(index/PAGE_SIZE);renderQuran();if(open)setTafsir(true);if(focus)focusVerse();return true;}
function renderQuran(){const surah=quranData[surahIndex];document.getElementById('surah-select').value=String(surahIndex);document.getElementById('jump-verse').max=String(surah.count);if(!surah.verses){if(document.getElementById('quran-reader').hidden)return;const want=surahIndex;document.getElementById('surah-heading').textContent='سورة '+surah.name;document.getElementById('verse-position').textContent='جارٍ تحميل السورة…';document.getElementById('verse-text').replaceChildren();loadSurah(want).then(()=>{if(want!==surahIndex)return;const o=pendingOpen,f=pendingFocus;pendingOpen=pendingFocus=false;renderQuran();if(o)setTafsir(true);if(f)focusVerse();}).catch(()=>{if(want===surahIndex)document.getElementById('verse-position').textContent='تعذّر تحميل السورة. تحقّق من الاتصال ثم أعد اختيار السورة.';});return;}const ranges=pageRanges(surah.verses.length);readingPage=Math.max(0,Math.min(readingPage,ranges.length-1));const range=ranges[readingPage];document.getElementById('surah-select').value=String(surahIndex);document.getElementById('surah-heading').textContent='سورة '+surah.name;document.getElementById('verse-position').textContent=surah.verses.length+' آيات · '+(ranges.length===1?'السورة كاملة':'مقطع قراءة '+(readingPage+1)+' من '+ranges.length+' · الآيات '+(range.start+1)+'–'+range.end+' — ليس صفحة مصحف مطبوعة');const flow=document.getElementById('verse-text');flow.replaceChildren();flow.style.fontSize=fontSize+'px';surah.verses.slice(range.start,range.end).forEach((ayah,offset)=>{const span=document.createElement('span');span.className='ayah-copy';span.textContent=ayah.text;const marker=document.createElement('button');marker.id='ayah-'+ayah.number;marker.type='button';marker.className='ayah-marker';marker.textContent=String(ayah.number);marker.setAttribute('aria-label','تفسير الآية '+ayah.number);marker.setAttribute('aria-pressed',String(range.start+offset===verseIndex));marker.addEventListener('click',()=>selectVerse(range.start+offset,true,false));flow.append(span,marker,document.createTextNode(' '));});document.getElementById('jump-verse').max=String(surah.verses.length);document.getElementById('reading-pagination').hidden=ranges.length<=1;document.getElementById('reading-prev').disabled=readingPage===0;document.getElementById('reading-next').disabled=readingPage===ranges.length-1;document.getElementById('reading-page-label').textContent='مقطع '+(readingPage+1)+' / '+ranges.length;updateTafsir();updateFontButtons();}
function updateFontButtons(){document.getElementById('font-size-label').textContent=fontSize+'px';document.getElementById('font-smaller').disabled=fontSize<=26;document.getElementById('font-larger').disabled=fontSize>=48;}
function changeFont(delta){fontSize=Math.max(26,Math.min(48,fontSize+delta));document.getElementById('verse-text').style.fontSize=fontSize+'px';updateFontButtons();}
function jumpToVerse(raw){if(!/^\d+$/.test(String(raw)))return false;const number=Number(raw);return selectVerse(number-1,true,true);}
document.getElementById('surah-select').addEventListener('change',event=>{const index=Number(event.target.value);if(!Number.isInteger(index)||index<0||index>=quranData.length)return;surahIndex=index;verseIndex=0;readingPage=0;setTafsir(false);document.getElementById('jump-message').textContent='';renderQuran();});
document.getElementById('jump-form').addEventListener('submit',event=>{event.preventDefault();const valid=jumpToVerse(document.getElementById('jump-verse').value);document.getElementById('jump-message').textContent=valid?'تم تحديد الآية وعرض تفسيرها.':'أدخل رقم آية صحيحًا من 1 إلى '+quranData[surahIndex].count;});
document.getElementById('font-smaller').addEventListener('click',()=>changeFont(-2));document.getElementById('font-larger').addEventListener('click',()=>changeFont(2));
for(const [id,delta] of [['reading-prev',-1],['reading-next',1]])document.getElementById(id).addEventListener('click',()=>{const next=readingPage+delta;if(next<0||next>=pageRanges(quranData[surahIndex].count).length)return;selectVerse(next*PAGE_SIZE,false,true);});
document.getElementById('tafsir-toggle').addEventListener('click',()=>setTafsir(document.getElementById('tafsir-panel').hidden));
function bookmarkMessage(text){document.getElementById('bookmark-status').textContent=text;}
function validBookmark(value){return value&&Object.keys(value).length===3&&Number.isInteger(value.surah)&&quranData.some(s=>s.id===value.surah)&&Number.isInteger(value.verse)&&value.verse>=1&&value.verse<=quranData.find(s=>s.id===value.surah).count&&Number.isInteger(value.font)&&value.font>=26&&value.font<=48;}
function restoreBookmark(){try{const raw=window.localStorage.getItem(BOOKMARK_KEY);if(!raw)return;const saved=JSON.parse(raw);if(!validBookmark(saved)){bookmarkMessage('الموضع المحفوظ غير صالح؛ لم يُستخدم.');return;}surahIndex=quranData.findIndex(s=>s.id===saved.surah);verseIndex=saved.verse-1;fontSize=saved.font;readingPage=Math.floor(verseIndex/PAGE_SIZE);bookmarkMessage('استُعيد موضعك المحفوظ على هذا المتصفح فقط.');}catch{bookmarkMessage('التخزين المحلي غير متاح أو الموضع غير قابل للقراءة؛ يمكنك المتابعة دون حفظ.');}}
document.getElementById('bookmark-save').addEventListener('click',()=>{try{window.localStorage.setItem(BOOKMARK_KEY,JSON.stringify({surah:quranData[surahIndex].id,verse:verseIndex+1,font:fontSize}));bookmarkMessage('حُفظ الموضع محليًا فقط؛ لا مزامنة أو حساب.');}catch{bookmarkMessage('تعذّر الحفظ في هذا المتصفح؛ القراءة تعمل دون تخزين.');}});
document.getElementById('bookmark-clear').addEventListener('click',()=>{try{window.localStorage.removeItem(BOOKMARK_KEY);bookmarkMessage('مُسح الموضع المحفوظ محليًا.');}catch{bookmarkMessage('التخزين المحلي غير متاح؛ تعذّر مسح الموضع.');}});
restoreBookmark();window.__quranShown=renderQuran;renderQuran();

const audioPlayer=document.getElementById('quran-audio');
const RECITER_KEY='skillpost-quran-reciter-v1';
let audioGeneration=0,audioRequested=false,reciterCatalog=null,activeReciter=null;
function reciterById(id){return reciterCatalog&&typeof id==='string'?reciterCatalog.reciters.find(r=>r.id===id)||null:null;}
function defaultReciter(){return reciterById(reciterCatalog&&reciterCatalog.default_id)||(reciterCatalog&&reciterCatalog.reciters[0])||null;}
function validServer(server){return typeof server==='string'&&server.startsWith('https://')&&server.endsWith('/');}
function surahAudioUrl(surah,reciter){if(!reciter||!Number.isInteger(surah)||surah<1||surah>114||!Array.isArray(reciter.surah_list)||!reciter.surah_list.includes(surah)||!validServer(reciter.server))throw new Error('Invalid reciter or surah');return reciter.server+String(surah).padStart(3,'0')+'.mp3';}
function savedReciterId(){try{return window.localStorage.getItem(RECITER_KEY);}catch{return null;}}
function persistReciter(id){try{window.localStorage.setItem(RECITER_KEY,id);}catch{}}
function applyReciter(reciter,persist){if(!reciter)return;activeReciter=reciter;const select=document.getElementById('reciter-select');if(select&&select.value!==reciter.id)select.value=reciter.id;const heading=document.getElementById('audio-reciter-heading');if(heading)heading.textContent=reciter.name_ar;const moshaf=document.getElementById('audio-moshaf-label');if(moshaf)moshaf.textContent=reciter.moshaf_name;if(persist)persistReciter(reciter.id);updateAudioLabel();}
function fillReciterSelect(){const select=document.getElementById('reciter-select');if(!select||!reciterCatalog)return;const previous=select.value;select.replaceChildren();for(const reciter of reciterCatalog.reciters){const option=document.createElement('option');option.value=reciter.id;option.textContent=reciter.name_ar;select.append(option);}applyReciter(reciterById(savedReciterId())||reciterById(previous)||defaultReciter(),false);select.disabled=false;}
function audioStatus(text){document.getElementById('audio-status').textContent=text;}
function audioButtons(active,playing){document.getElementById('audio-play').disabled=!reciterCatalog||playing;document.getElementById('audio-pause').disabled=!playing;document.getElementById('audio-stop').disabled=!active;}
function stopAudio(message='توقف الصوت؛ التشغيل التالي يبدأ السورة من بدايتها.'){audioGeneration++;audioRequested=false;audioPlayer.pause();audioPlayer.removeAttribute('src');audioPlayer.load();audioButtons(false,false);audioStatus(message);}
async function playAudio(){const reciter=activeReciter||defaultReciter();if(!reciter){audioStatus('تعذّر تحميل قائمة القرّاء؛ القراءة غير متأثرة.');return;}const token=++audioGeneration;audioRequested=true;let url;try{url=surahAudioUrl(quranData[surahIndex].id,reciter);}catch{audioRequested=false;audioButtons(true,false);audioStatus('تعذّر بناء رابط التلاوة لهذا القارئ؛ القراءة غير متأثرة.');return;}if(audioPlayer.getAttribute('src')!==url)audioPlayer.setAttribute('src',url);audioButtons(true,true);audioStatus('جارٍ الاتصال بمصدر التلاوة…');try{await audioPlayer.play();if(token!==audioGeneration)return;audioButtons(true,true);audioStatus('تُتلى سورة '+quranData[surahIndex].name+' بصوت '+reciter.name_ar+'.');}catch{if(token!==audioGeneration)return;audioRequested=false;audioButtons(true,false);audioStatus('تعذّر التشغيل. تحقّق من الاتصال أو حاول التشغيل مجددًا؛ القراءة غير متأثرة.');}}
function pauseAudio(){audioGeneration++;audioRequested=false;audioPlayer.pause();audioButtons(true,false);audioStatus('التلاوة متوقفة مؤقتًا؛ اختر تشغيل / متابعة للاستكمال.');}
document.getElementById('audio-play').addEventListener('click',playAudio);document.getElementById('audio-pause').addEventListener('click',pauseAudio);document.getElementById('audio-stop').addEventListener('click',()=>stopAudio());
audioPlayer.addEventListener('ended',()=>{audioRequested=false;audioButtons(true,false);audioStatus('انتهت تلاوة السورة. لا انتقال أو تشغيل تلقائي.');});
audioPlayer.addEventListener('error',()=>{if(!audioPlayer.getAttribute('src'))return;audioGeneration++;audioRequested=false;audioButtons(true,false);audioStatus('تعذّر تحميل التلاوة من المصدر؛ القراءة غير متأثرة.');});
document.getElementById('surah-select').addEventListener('change',()=>{stopAudio('اختيرت سورة جديدة؛ لن يبدأ الصوت إلا باختيار التشغيل.');updateAudioLabel();});
document.getElementById('reciter-select').addEventListener('change',event=>{const reciter=reciterById(event.target.value);if(!reciter)return;const changed=!activeReciter||activeReciter.id!==reciter.id;applyReciter(reciter,true);if(changed)stopAudio('اختير قارئ جديد؛ لن يبدأ الصوت إلا باختيار التشغيل.');});
function updateAudioLabel(){document.getElementById('audio-surah-label').textContent='السورة المختارة: '+quranData[surahIndex].name;}
window.addEventListener('hashchange',()=>{if(location.hash.split('/')[0]!=='#quran-reader')stopAudio('توقف الصوت عند مغادرة القارئ.');});
