fetch('/data/reciters.json',{credentials:'omit'}).then(r=>{if(!r.ok)throw new Error('HTTP '+r.status);return r.json();}).then(data=>{if(!data||!Array.isArray(data.reciters)||!data.reciters.length)throw new Error('bad catalog');reciterCatalog=data;fillReciterSelect();audioButtons(false,false);}).catch(()=>{audioStatus('تعذّر تحميل قائمة القرّاء؛ القراءة غير متأثرة.');audioButtons(false,false);});

