const adhkarCounters=new Map();
function adhkarNormalize(value){return String(value).normalize('NFKD').replace(/[\u064B-\u065F\u0670\u0640]/g,'').replace(/[أإآٱ]/g,'ا').replace(/ى/g,'ي').toLowerCase().trim();}
function filteredAdhkar(query,category){const term=adhkarNormalize(query);return adhkarData.filter(entry=>(category==='all'||entry.category===category)&&adhkarNormalize(entry.text+' '+entry.category+' '+entry.label+' حصن المسلم '+entry.sourceReference).includes(term));}
function counterValue(entry){return adhkarCounters.get(entry.id)||0;}
function incrementDhikr(id){const entry=adhkarData.find(item=>item.id===id);if(!entry||!Number.isInteger(entry.count)||entry.count<1)return false;adhkarCounters.set(id,Math.min(entry.count,counterValue(entry)+1));return true;}
function resetDhikr(id){adhkarCounters.delete(id);}
function adhkarCard(entry){const article=document.createElement('article');article.className='card adhkar-card';const top=document.createElement('div');top.className='dhikr-top';const tag=document.createElement('span');tag.className='status';tag.textContent=entry.category;const heading=document.createElement('h2');heading.textContent=entry.label;top.append(tag,heading);const text=document.createElement('div');text.className='dhikr-text';text.lang='ar';text.textContent=entry.text;const reference=document.createElement('p');reference.className='dhikr-reference';reference.textContent='حصن المسلم — المدخل '+entry.sourceReference+' · OpenDua '+entry.sourceEntry+' · '+entry.duaId;article.append(top,text,reference);const source=document.createElement('p');source.className='mini-label';source.textContent='موضع المصدر: '+entry.sourceTitle+(entry.sourceCondition?' · '+entry.sourceCondition:'');article.append(source);if(Number.isInteger(entry.count)&&entry.count>0){const controls=document.createElement('div');controls.className='dhikr-counter';const label=document.createElement('span');label.textContent='العدد الوارد في المصدر: '+entry.count;const progress=document.createElement('output');progress.setAttribute('aria-live','polite');const plus=document.createElement('button');plus.type='button';plus.className='button';plus.textContent='عدّ تكرار';plus.setAttribute('aria-label','عد تكرار للمدخل '+entry.sourceReference);const reset=document.createElement('button');reset.type='button';reset.className='button';reset.textContent='تصفير';function update(){progress.textContent=counterValue(entry)+' / '+entry.count;plus.disabled=counterValue(entry)>=entry.count;}plus.addEventListener('click',()=>{incrementDhikr(entry.id);update();});reset.addEventListener('click',()=>{resetDhikr(entry.id);update();});update();controls.append(label,progress,plus,reset);article.append(controls);}else{const note=document.createElement('p');note.className='mini-label';note.textContent='لم يُذكر عدد تكرار صريح لهذه الصيغة في ملف المصدر؛ لا عدّاد لها هنا.';article.append(note);}return article;}
function renderAdhkar(){const matches=filteredAdhkar(document.getElementById('adhkar-search').value,document.getElementById('adhkar-category').value);const list=document.getElementById('adhkar-list');list.replaceChildren(...matches.map(adhkarCard));if(!matches.length){const empty=document.createElement('p');empty.className='no-results';empty.textContent='لا توجد نتائج مطابقة. جرّب كلمة أخرى أو جميع الأقسام.';list.append(empty);}document.getElementById('adhkar-results').textContent=matches.length+' بطاقة من أصل '+adhkarData.length+' — مختارات غير شاملة';}
document.getElementById('adhkar-search').addEventListener('input',renderAdhkar);document.getElementById('adhkar-category').addEventListener('change',renderAdhkar);document.getElementById('adhkar-reset-all').addEventListener('click',()=>{adhkarCounters.clear();renderAdhkar();});renderAdhkar();

