const prayerZoneAliases={'Europe/Kiev':'Europe/Kyiv'};
function fillCityPresets(){const select=document.getElementById('city-preset');if(!select)return;const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent='اختر مدينة أو أدخل إحداثياتك';const groupOrder=[];const byGroup=new Map();for(const [id,city] of Object.entries(prayerCities)){if(!byGroup.has(city.group)){byGroup.set(city.group,[]);groupOrder.push(city.group);}byGroup.get(city.group).push([id,city]);}select.replaceChildren(placeholder);for(const label of groupOrder){const optgroup=document.createElement('optgroup');optgroup.label=label;for(const [id,city] of byGroup.get(label)){const option=document.createElement('option');option.value=id;option.textContent=city.note?city.label+' — '+city.note:city.label;optgroup.append(option);}select.append(optgroup);}}
function prayerCityForZone(zone){const resolved=prayerZoneAliases[zone]||zone;const matches=Object.entries(prayerCities).filter(([,city])=>city.zone===resolved);if(!matches.length)return null;return matches.find(([,city])=>city.primary)||matches[0];}
function applyCityPreset(id,statusText){const city=prayerCities[id];if(!city)return false;document.getElementById('prayer-lat').value=city.lat;document.getElementById('prayer-lon').value=city.lon;document.getElementById('prayer-zone').value=city.zone;document.getElementById('city-preset').value=id;if(statusText)document.getElementById('location-status').textContent=statusText;return true;}
function suggestCityFromDeviceZone(prefix){const status=document.getElementById('location-status');const zone=Intl.DateTimeFormat().resolvedOptions().timeZone;const match=prayerCityForZone(zone);const manual='اختر مدينة من القائمة أو أدخل الإحداثيات يدويًا.';if(!match){status.textContent=(prefix?prefix+' ':'')+manual;return;}const [id,city]=match;applyCityPreset(id,(prefix?prefix+' ':'')+'اختيرت '+city.label+' تلقائيًا من المنطقة الزمنية للجهاز ('+zone+'). هذه إحداثيات المدينة المختارة وليست موقعك الدقيق، ولا يُحفظ شيء. راجعها ثم اضغط تطبيق.');}
function geolocateErrorMessage(error){const code=error&&error.code;if(code===1)return 'رُفض إذن الموقع. اضغط أيقونة القفل بجانب الرابط، واسمح بالموقع، ثم حدّث الصفحة وحاول مرة أخرى.';if(code===2)return 'تعذّر على الجهاز تحديد الموقع.';if(code===3)return 'انتهت مهلة تحديد الموقع.';return 'تعذّر تحديد الموقع.';}
function requestPrayerLocation(highAccuracy,isRetry){const status=document.getElementById('location-status');navigator.geolocation.getCurrentPosition(position=>{document.getElementById('prayer-lat').value=position.coords.latitude;document.getElementById('prayer-lon').value=position.coords.longitude;document.getElementById('prayer-zone').value=Intl.DateTimeFormat().resolvedOptions().timeZone;document.getElementById('city-preset').value='';status.textContent='أُدخل الموقع في الذاكرة فقط؛ راجع المنطقة والتاريخ ثم اضغط تطبيق.';},error=>{const retryable=error&&(error.code===2||error.code===3);if(!isRetry&&retryable){status.textContent='تعذّر التحديد؛ نعيد المحاولة بدقة أعلى…';requestPrayerLocation(true,true);return;}suggestCityFromDeviceZone(geolocateErrorMessage(error));},{enableHighAccuracy:!!highAccuracy,timeout:30000,maximumAge:isRetry?0:600000});}
fillCityPresets();
const prayerNames={fajr:'الفجر',sunrise:'الشروق',dhuhr:'الظهر',asr:'العصر',maghrib:'المغرب',isha:'العشاء'};let appliedPrayer=null;
function validatePrayerInput(raw){const required=['lat','lon','zone','date'];if(required.some(key=>String(raw[key]??'').trim()===''))throw Error('أدخل الإحداثيات والمنطقة الزمنية والتاريخ أولًا.');const lat=Number(raw.lat),lon=Number(raw.lon);if(!Number.isFinite(lat)||lat< -90||lat>90||!Number.isFinite(lon)||lon< -180||lon>180)throw Error('الإحداثيات خارج الحدود أو ليست أرقامًا منتهية.');if(!/^\d{4}-\d{2}-\d{2}$/.test(raw.date))throw Error('التاريخ غير صالح.');const [y,m,d]=raw.date.split('-').map(Number);const date=new Date(Date.UTC(y,m-1,d));if(y<1900||y>2100||date.toISOString().slice(0,10)!==raw.date)throw Error('اختر تاريخًا صحيحًا بين1900 و2100.');if(typeof raw.zone!=='string'||/^[+-]/.test(raw.zone))throw Error('استخدم اسم منطقة IANA لا إزاحة رقمية ثابتة.');try{new Intl.DateTimeFormat('en',{timeZone:raw.zone}).format(date);}catch{throw Error('اسم المنطقة الزمنية IANA غير صالح.');}if(!['MWL','ISNA','Egypt','Karachi'].includes(raw.method)||!['Standard','Hanafi'].includes(raw.madhab)||!['None','NightMiddle'].includes(raw.high))throw Error('اختر طريقة وعصرًا وسياسة معروفة.');return {lat,lon,zone:raw.zone,date:raw.date,method:raw.method,madhab:raw.madhab,high:raw.high,parts:[y,m,d]};}
function bearingToKaaba(lat,lon){const r=Math.PI/180,p1=lat*r,p2=21.4225*r,dl=(39.8262-lon)*r;const y=Math.sin(dl)*Math.cos(p2),x=Math.cos(p1)*Math.sin(p2)-Math.sin(p1)*Math.cos(p2)*Math.cos(dl);if(Math.abs(lat)>89.999999||Math.hypot(x,y)<1e-10)return null;return (Math.atan2(y,x)/r+360)%360;}
function utcPrayerTimes(input,high){const calc=new PrayTimes(input.method);calc.adjust({asr:input.madhab,highLats:high});return calc.getTimes(input.parts,[input.lat,input.lon,0],0,0,'Float');}
function eventInstant(date,hours){if(!Number.isFinite(hours))return null;return new Date(Date.parse(date+'T00:00:00Z')+Math.round(hours*60)*60000);}
function localEvent(instant,zone){if(!instant)return null;return new Intl.DateTimeFormat('en-GB',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZoneName:'longOffset'}).format(instant);}
function civilHijri(date){const fmt=new Intl.DateTimeFormat('ar-u-ca-islamic-civil',{calendar:'islamic-civil',timeZone:'UTC',year:'numeric',month:'long',day:'numeric'});if(fmt.resolvedOptions().calendar!=='islamic-civil')return null;return fmt.format(new Date(date+'T12:00:00Z'));}
function calculatePrayer(input){const raw=utcPrayerTimes(input,'None'),solarNight=Number.isFinite(raw.sunrise)&&Number.isFinite(raw.sunset);const adjusted=input.high==='NightMiddle'&&solarNight?utcPrayerTimes(input,'NightMiddle'):raw;const events=Object.keys(prayerNames).map(key=>{const hours=adjusted[key],estimated=input.high!=='None'&&solarNight&&Number.isFinite(hours)&&(!Number.isFinite(raw[key])||Math.abs(hours-raw[key])>1e-6);return {key,hours,estimated,instant:eventInstant(input.date,hours)};});let hijri=null;try{hijri=civilHijri(input.date);}catch{}return {events,solarNight,bearing:bearingToKaaba(input.lat,input.lon),hijri};}
function renderPrayer(input,result){document.getElementById('prayer-results').hidden=false;const label=input.date+' · '+input.lat+', '+input.lon+' · '+input.zone+' · '+input.method+' · العصر '+input.madhab+' · سياسة '+input.high;document.getElementById('applied-inputs').textContent='الإعدادات المطبّقة فقط: '+label;const grid=document.getElementById('prayer-times');grid.replaceChildren();for(const event of result.events){const card=document.createElement('article');card.className='prayer-time';const title=document.createElement('h3');title.textContent=prayerNames[event.key];const time=document.createElement('p');time.dir='ltr';time.textContent=localEvent(event.instant,input.zone)||'غير متاح';const status=document.createElement('small');status.textContent=!event.instant?'الحدث غير قابل للحساب لهذه المدخلات؛ لا وقت مختلق.':event.estimated?'تقدير بسياسة نصف الليل المختارة، وليس وقت الزاوية الفلكية.':'حساب فلكي بالطريقة المختارة.';card.append(title,time,status);grid.append(card);}document.getElementById('polar-note').textContent=!result.solarNight?'لا يوجد شروق أو غروب قابل للحساب؛ تقدير نصف الليل غير قابل للتطبيق، ولا يُستبدل بيوم أو مدينة أخرى.':input.high==='None'?'التقدير معطّل؛ الزوايا غير المتحققة تبقى غير متاحة.':'أي وقت تغيّر بسياسة نصف الليل موسوم كتقدير صراحة.';document.getElementById('qibla-bearing').textContent=result.bearing===null?'الاتجاه غير محدد عند هذا الموضع.':result.bearing.toFixed(1)+'° من الشمال الحقيقي';document.getElementById('hijri-result').textContent=result.hijri||'التقويم islamic-civil غير مدعوم في هذا المتصفح؛ لا تاريخ بديل غير معلن.';const fajr=result.events.find(e=>e.key==='fajr');document.getElementById('home-prayer-summary').textContent='إعدادات مطبّقة: '+input.date+' · '+input.zone+' · '+input.lat+', '+input.lon+'؛ الفجر '+(localEvent(fajr.instant,input.zone)||'غير متاح')+(fajr.estimated?' (تقدير نصف الليل)':'')+'؛ الهجري المدني: '+(result.hijri||'غير مدعوم');}
document.getElementById('city-preset').addEventListener('change',event=>{if(!prayerCities[event.target.value])return;applyCityPreset(event.target.value,'مثال مدينة فقط، ليس تحديدًا لموقعك. اختر تاريخًا ثم طبّق.');});
document.getElementById('prayer-form').addEventListener('submit',event=>{event.preventDefault();try{const input=validatePrayerInput({lat:document.getElementById('prayer-lat').value,lon:document.getElementById('prayer-lon').value,zone:document.getElementById('prayer-zone').value,date:document.getElementById('prayer-date').value,method:document.getElementById('prayer-method').value,madhab:document.getElementById('prayer-madhab').value,high:document.getElementById('prayer-high').value});const result=calculatePrayer(input);appliedPrayer={input,result};renderPrayer(input,result);document.getElementById('prayer-error').textContent='';}catch(error){document.getElementById('prayer-error').textContent=error.message+' النتائج السابقة إن وجدت تخص آخر إعدادات مطبّقة فقط.';}});
document.getElementById('prayer-geolocate').addEventListener('click',()=>{const status=document.getElementById('location-status');if(!navigator.geolocation){suggestCityFromDeviceZone('تحديد الموقع غير متاح في هذا المتصفح.');return;}status.textContent='بانتظار إذنك من المتصفح؛ لا حفظ للإحداثيات.';requestPrayerLocation(false,false);});

